def avanti(apps, schema_editor):
    """Il conteggio cassa resta a chi lo faceva: gruppo titolare e
    utenti con l'eccezione "consenti" sulle Finanze."""
    Group = apps.get_model('auth', 'Group')
    PermessoGruppo = apps.get_model('auth_system', 'PermessoGruppo')
    PermessoUtente = apps.get_model('auth_system', 'PermessoUtente')
    titolare, _ = Group.objects.get_or_create(name='titolare')
    PermessoGruppo.objects.get_or_create(sezione='conteggio_cassa', gruppo=titolare)
    for p in PermessoUtente.objects.filter(sezione='finanze', consenti=True):
        PermessoUtente.objects.get_or_create(sezione='conteggio_cassa', user_id=p.user_id,
                                             defaults={'consenti': True})


